//! store.rs
//! ========
//! Zentraler Zugriff auf die einzige Speicherdatei `mem.json`.
//!
//! Das Format ist **bitgleich** zur Python-Fassung (`store.py`), damit ein
//! bestehender Spielstand weiterbenutzt werden kann:
//!
//! ```json
//! {
//!   "_generated": "generated by PyGameZ at ...",
//!   "mem":      { "lang": "de" },
//!   "profiles": { "active": "p1", "order": ["p1"],
//!                 "list": { "p1": {"name": "Lama", "icon": "llama",
//!                                  "color": 0, "created": "...", "seen": "..."} } },
//!   "players":  { "p1": { "highscores": {}, "achievements": {}, ... } }
//! }
//! ```
//!
//! Jedes Modul liest und schreibt nur seinen eigenen **Abschnitt** ueber
//! [`load_section`] / [`save_section`]; der Rest der Datei bleibt dabei
//! erhalten. Die Abschnitte landen automatisch beim aktiven Profil - nur die
//! in [`SHARED_SECTIONS`] genannten (die Sprache) gelten geraeteweit.

use std::collections::BTreeMap;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::sync::{Mutex, OnceLock};

use serde_json::{json, Map, Value};

/// Ein Abschnitt der Speicherdatei (entspricht einem Python-dict).
pub type Section = Map<String, Value>;

/// Abschnitte, die fuer das ganze Geraet gelten (nicht je Profil).
pub const SHARED_SECTIONS: &[&str] = &["mem"];

/// Mehr Profile passen weder auf den Bildschirm noch in einen Haushalt.
pub const MAX_PROFILES: usize = 8;

/// Standard-Profil-id (erstes Profil, bekommt bei der Migration alle Altdaten).
pub const FIRST_ID: &str = "p1";

const PROFILES: &str = "profiles";
const PLAYERS: &str = "players";

// ---------------------------------------------------------------------------
// Ablageort
// ---------------------------------------------------------------------------

static DIR: OnceLock<PathBuf> = OnceLock::new();

/// Ermittelt den Datenordner.
///
/// Normalfall: neben der ausfuehrbaren Datei (wie bei der PyInstaller-.exe).
/// Waehrend der Entwicklung liegt die .exe aber in `rust.output/debug/` -
/// dort haetten die Spielstaende nichts verloren, weil dieser Ordner reiner
/// Build-Output ist. Dann wird `rust/data/` benutzt. Ueberschreibbar mit der
/// Umgebungsvariablen `PYGAMEZ_DATA_DIR`.
fn detect_dir() -> PathBuf {
    if let Ok(p) = std::env::var("PYGAMEZ_DATA_DIR") {
        if !p.trim().is_empty() {
            return PathBuf::from(p);
        }
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let here = dir.file_name().and_then(|s| s.to_str()).unwrap_or("");
            let up = dir
                .parent()
                .and_then(|p| p.file_name())
                .and_then(|s| s.to_str())
                .unwrap_or("");
            let in_build = matches!(here, "debug" | "release") && up == "rust.output";
            if in_build {
                if let Some(root) = dir.parent().and_then(|p| p.parent()) {
                    return root.join("rust").join("data");
                }
            }
            return dir.to_path_buf();
        }
    }
    PathBuf::from(".")
}

/// Ordner, in dem die Spieldaten liegen (neben der .exe bzw. `rust/data/`).
pub fn data_dir() -> PathBuf {
    DIR.get_or_init(|| {
        let dir = detect_dir();
        let _ = std::fs::create_dir_all(&dir);
        dir
    })
    .clone()
}

/// Vollstaendiger Pfad einer Datei im Datenordner (z.B. `stats.pgzlamastats`).
pub fn path_for(filename: &str) -> PathBuf {
    data_dir().join(filename)
}

fn mem_path() -> PathBuf {
    path_for("mem.json")
}

// ---------------------------------------------------------------------------
// Datei lesen / schreiben
// ---------------------------------------------------------------------------

fn read_json(path: &Path) -> Option<Map<String, Value>> {
    let text = std::fs::read_to_string(path).ok()?;
    match serde_json::from_str::<Value>(&text) {
        Ok(Value::Object(map)) => Some(map),
        _ => None,
    }
}

/// Schreibt `value` als JSON, ohne dass ein Absturz die Datei zerstoeren kann.
///
/// Erst in eine Temp-Datei daneben, dann per `rename` an die richtige Stelle.
/// Die vorherige Fassung bleibt als `<pfad>.bak` liegen. Fehler (z.B. fehlende
/// Schreibrechte) werden geschluckt, damit das Spiel ohne Persistenz
/// weiterlaeuft - genau wie in `store.py`.
pub fn write_json_atomic(path: &Path, value: &Value) -> bool {
    let Ok(text) = serde_json::to_string_pretty(value) else {
        return false;
    };
    write_text_atomic(path, &text)
}

/// Text so, wie Python ihn im Textmodus schreibt (`open(pfad, "w")`): unter
/// Windows wird jedes `\n` zu `\r\n` (`os.linesep`). So sind `mem.json`,
/// `ugc.json` und geteilte Dateien Byte fuer Byte wie die der Python-Fassung.
pub fn text_mode(text: &str) -> std::borrow::Cow<'_, str> {
    if cfg!(windows) && text.contains('\n') {
        std::borrow::Cow::Owned(text.replace('\n', "\r\n"))
    } else {
        std::borrow::Cow::Borrowed(text)
    }
}

/// Wie [`write_json_atomic`], nur mit fertigem Text (im Textmodus, siehe
/// [`text_mode`]).
pub fn write_text_atomic(path: &Path, text: &str) -> bool {
    let tmp = path.with_extension(format!(
        "{}tmp",
        path.extension()
            .and_then(|e| e.to_str())
            .map(|e| format!("{e}."))
            .unwrap_or_default()
    ));
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let ok = (|| -> std::io::Result<()> {
        let mut f = std::fs::File::create(&tmp)?;
        f.write_all(text_mode(text).as_bytes())?;
        f.flush()?;
        let _ = f.sync_all();
        Ok(())
    })()
    .is_ok();
    if !ok {
        let _ = std::fs::remove_file(&tmp);
        return false;
    }
    if path.exists() {
        let mut bak = path.as_os_str().to_os_string();
        bak.push(".bak");
        let _ = std::fs::rename(path, PathBuf::from(bak));
    }
    if std::fs::rename(&tmp, path).is_err() {
        let _ = std::fs::remove_file(&tmp);
        return false;
    }
    true
}

/// Liest `mem.json` roh; faellt bei Schaden auf `mem.json.bak` zurueck.
fn read_raw() -> Map<String, Value> {
    let path = mem_path();
    if let Some(map) = read_json(&path) {
        return map;
    }
    let mut bak = path.as_os_str().to_os_string();
    bak.push(".bak");
    read_json(Path::new(&bak)).unwrap_or_default()
}

fn timestamp() -> String {
    // Ohne chrono: Sekunden seit Epoche in Datum/Uhrzeit umrechnen.
    let secs = crate::store::local_secs();
    let (y, mo, d, h, mi, s) = civil_from_unix(secs);
    format!("{y:04}-{mo:02}-{d:02} {h:02}:{mi:02}:{s:02}")
}

/// Sekunden der **Ortszeit**, als waeren sie UTC - [`civil_from_unix`]
/// macht daraus Datum und Uhrzeit, wie Python sie mit `time.localtime`
/// sieht. Hier stand UTC; dann lag der Statistik-Tag um Mitternacht
/// eine bis zwei Stunden daneben, und die Nachteule kam nie.
pub fn local_secs() -> i64 {
    chrono::Local::now().naive_local().and_utc().timestamp()
}

/// Wochentag der Ortszeit, Montag = 0 (wie `date.weekday()`).
pub fn weekday_of(datum: &str) -> Option<u32> {
    use chrono::Datelike;
    chrono::NaiveDate::parse_from_str(datum, "%Y-%m-%d").ok().map(|d| d.weekday().num_days_from_monday())
}

/// Das Datum `tage` Tage nach `datum` (`YYYY-MM-DD`).
pub fn add_days(datum: &str, tage: i64) -> Option<String> {
    let d = chrono::NaiveDate::parse_from_str(datum, "%Y-%m-%d").ok()?;
    Some((d + chrono::Duration::days(tage)).format("%Y-%m-%d").to_string())
}

/// Ein aufgeschluesselter Zeitpunkt: Jahr, Monat, Tag, Stunde, Minute, Sekunde.
pub type CivilTime = (i64, u32, u32, u32, u32, u32);

/// Rechnet Unix-Sekunden (UTC) in (Jahr, Monat, Tag, Stunde, Minute, Sekunde).
///
/// Nach Howard Hinnants `civil_from_days` - reicht voellig, wir brauchen die
/// Zeitangaben nur als lesbaren Stempel in den Dateien.
pub fn civil_from_unix(secs: i64) -> CivilTime {
    let days = secs.div_euclid(86_400);
    let rem = secs.rem_euclid(86_400);
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (
        y,
        m,
        d,
        (rem / 3600) as u32,
        ((rem % 3600) / 60) as u32,
        (rem % 60) as u32,
    )
}

/// Heutiges Datum als `YYYY-MM-DD` (fuer Statistik-Tage und Tagesraetsel).
pub fn today() -> String {
    let secs = crate::store::local_secs();
    let (y, m, d, _, _, _) = civil_from_unix(secs);
    format!("{y:04}-{m:02}-{d:02}")
}

// ---------------------------------------------------------------------------
// Profil-Kopfdaten
// ---------------------------------------------------------------------------

/// Kopfdaten eines Spielerprofils (Name, Symbol, Farbe, Zeitstempel).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProfileMeta {
    pub name: String,
    pub icon: String,
    pub color: i64,
    pub created: String,
    pub seen: String,
}

/// `_blank_meta(name)` (store.py)
impl Default for ProfileMeta {
    fn default() -> Self {
        Self {
            name: String::new(),
            icon: "llama".into(),
            color: 0,
            created: stamp_minute(),
            seen: stamp_minute(),
        }
    }
}

/// Zeitstempel der Profil-Kopfdaten: `time.strftime("%Y-%m-%d %H:%M")`.
fn stamp_minute() -> String {
    timestamp()[..16].to_string()
}

impl ProfileMeta {
    /// `_clean_meta(raw, fallback_name)` (store.py) - fehlertolerant, und
    /// was Python behaelt, behaelt auch Rust (z.B. ein Symbol, das erst eine
    /// neuere Fassung kennt: die Anzeige faellt in `profiles::icon_of` auf
    /// das Lama zurueck, gespeichert bleibt es).
    fn from_value(raw: &Value, fallback_name: &str) -> Self {
        let mut meta = ProfileMeta { name: fallback_name.to_string(), ..Default::default() };
        let Some(obj) = raw.as_object() else {
            return meta;
        };
        if let Some(Value::String(name)) = obj.get("name") {
            meta.name = name.trim().chars().take(crate::profiles::MAX_NAME).collect();
        }
        if let Some(Value::String(icon)) = obj.get("icon") {
            if !icon.is_empty() {
                meta.icon = icon.chars().take(24).collect();
            }
        }
        // isinstance(color, int) and not isinstance(color, bool)
        if let Some(Value::Number(n)) = obj.get("color") {
            if let Some(c) = n.as_i64() {
                meta.color = c.clamp(0, 11);
            } else if n.is_u64() {
                meta.color = 11;
            }
        }
        for (key, slot) in [("created", &mut meta.created), ("seen", &mut meta.seen)] {
            if let Some(Value::String(v)) = obj.get(key) {
                if !v.is_empty() {
                    *slot = v.chars().take(19).collect();
                }
            }
        }
        meta
    }

    fn to_value(&self) -> Value {
        json!({
            "name": self.name,
            "icon": self.icon,
            "color": self.color,
            "created": self.created,
            "seen": self.seen,
        })
    }
}

/// Benutzername des Betriebssystems als Vorschlag fuer das erste Profil.
fn os_user_name() -> String {
    let raw = std::env::var("USERNAME")
        .or_else(|_| std::env::var("USER"))
        .unwrap_or_default();
    let name: String = raw.trim().chars().take(crate::profiles::MAX_NAME).collect();
    if name.is_empty() || !crate::swear::is_clean(&name) {
        String::new()
    } else {
        name
    }
}

// ---------------------------------------------------------------------------
// Normalisierung / Migration
// ---------------------------------------------------------------------------

/// Pythons `str(x)` fuer die Profil-ids aus `order`/`active`.
fn py_str(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => if *b { "True" } else { "False" }.into(),
        Value::Null => "None".into(),
        other => other.to_string(),
    }
}

/// `_normalize(data)` (store.py): bringt alte Formate auf die aktuelle
/// Struktur. Rueckgabe: (normalisiertes Dict, wurde geaendert?).
///
/// Wie in Python geht dabei nichts verloren: Profile ueber `MAX_PROFILES`
/// und Spielerdaten ohne Profil bleiben stehen, die Reihenfolge der Profil-
/// Liste bleibt die der Datei.
fn normalize(mut data: Map<String, Value>) -> (Map<String, Value>, bool) {
    let mut changed = false;

    // Abschnitt "mem": frueher lagen Schluessel wie "lang" direkt oben.
    if !data.get("mem").is_some_and(Value::is_object) {
        let mut mem = Map::new();
        if let Some(lang) = data.shift_remove("lang") {
            mem.insert("lang".into(), lang);
        }
        data.insert("mem".into(), Value::Object(mem));
        changed = true;
    }

    // --- Profile -----------------------------------------------------------
    // Fehlt der Profil-Abschnitt, stammt die Datei aus einer Version vor dem
    // Profil-Update: alle vorhandenen Spiel-Abschnitte wandern in Profil 1.
    let mut profiles = data.get(PROFILES).cloned().unwrap_or(Value::Null);
    let list_ok = profiles.get("list").and_then(Value::as_object).is_some_and(|l| !l.is_empty());
    if !profiles.is_object() || !list_ok {
        let mut moved = Map::new();
        let keys: Vec<String> = data
            .keys()
            .filter(|k| *k != "_generated" && !SHARED_SECTIONS.contains(&k.as_str()) && *k != PROFILES && *k != PLAYERS)
            .cloned()
            .collect();
        for k in keys {
            if let Some(v @ Value::Object(_)) = data.shift_remove(&k) {
                moved.insert(k, v);
            }
        }
        let mut players = match data.get(PLAYERS) {
            Some(Value::Object(p)) => p.clone(),
            _ => Map::new(),
        };
        if let Some(Value::Object(old)) = players.get(FIRST_ID) {
            let mut old = old.clone();
            for (k, v) in moved {
                old.insert(k, v);
            }
            moved = old;
        }
        players.insert(FIRST_ID.into(), Value::Object(moved));
        let meta = ProfileMeta { name: os_user_name(), ..Default::default() };
        profiles = json!({"active": FIRST_ID, "order": [FIRST_ID], "list": {FIRST_ID: meta.to_value()}});
        data.insert(PROFILES.into(), profiles.clone());
        data.insert(PLAYERS.into(), Value::Object(players));
        changed = true;
    }

    // Verwaltungsdaten saeubern (beschaedigte Datei darf nicht alles kippen).
    if !data.get(PLAYERS).is_some_and(Value::is_object) {
        data.insert(PLAYERS.into(), Value::Object(Map::new()));
        changed = true;
    }
    let mut plist = Map::new();
    if let Some(Value::Object(list)) = profiles.get("list") {
        for (pid, meta) in list {
            if !pid.is_empty() {
                plist.insert(pid.clone(), ProfileMeta::from_value(meta, "").to_value());
            }
        }
    }
    if plist.is_empty() {
        let meta = ProfileMeta { name: os_user_name(), ..Default::default() };
        plist.insert(FIRST_ID.into(), meta.to_value());
        changed = true;
    }
    let mut order: Vec<String> = match profiles.get("order") {
        Some(Value::Array(a)) => a.iter().map(py_str).filter(|p| plist.contains_key(p)).collect(),
        _ => Vec::new(),
    };
    for pid in plist.keys() {
        if !order.contains(pid) {
            order.push(pid.clone());
        }
    }
    // str(profiles.get("active") or "")
    let falsy = |v: &Value| match v {
        Value::Null => true,
        Value::Bool(b) => !b,
        Value::Number(n) => n.as_f64() == Some(0.0),
        Value::String(s) => s.is_empty(),
        Value::Array(a) => a.is_empty(),
        Value::Object(o) => o.is_empty(),
    };
    let mut active = match profiles.get("active") {
        Some(v) if !falsy(v) => py_str(v),
        _ => String::new(),
    };
    if !plist.contains_key(&active) {
        active = order[0].clone();
    }
    let new_profiles = json!({"active": active, "order": order, "list": plist});
    // Wie Pythons dict-Vergleich: ohne Ruecksicht auf die Reihenfolge.
    if new_profiles != profiles {
        data.insert(PROFILES.into(), new_profiles);
        changed = true;
    }
    let players = data.get_mut(PLAYERS).and_then(Value::as_object_mut).expect("players ist ein Dict");
    for pid in plist.keys() {
        if !players.get(pid).is_some_and(Value::is_object) {
            players.insert(pid.clone(), Value::Object(Map::new()));
            changed = true;
        }
    }

    // Abschnitt "highscores" des aktiven Profils: ggf. aus alter
    // highscores.json uebernehmen (nur beim allerersten Start relevant).
    let slot = players.get_mut(&active).and_then(Value::as_object_mut).expect("Profil-Abschnitt ist ein Dict");
    if !slot.get("highscores").is_some_and(Value::is_object) {
        let legacy = read_json(&path_for("highscores.json")).unwrap_or_default();
        slot.insert("highscores".into(), Value::Object(legacy));
        changed = true;
    }
    (data, changed)
}

// ---------------------------------------------------------------------------
// Laden / Speichern
// ---------------------------------------------------------------------------

/// `load()` - liest die komplette, normalisierte Speicherdatei; musste dabei
/// etwas umgebaut werden, wird sie gleich zurueckgeschrieben (wie Python).
pub fn load() -> Map<String, Value> {
    let (data, changed) = normalize(read_raw());
    if changed {
        save(data.clone());
    }
    data
}

/// Schreibt die komplette Speicherdatei (mit Erzeugungs-Stempel).
pub fn save(data: Map<String, Value>) -> bool {
    // Wie store.py: "_generated" (Anlege-Datum der Datei) steht immer als
    // erster Eintrag, ein vorhandener Stempel bleibt erhalten; danach alles
    // in der Reihenfolge des Dicts.
    let stamp = match data.get("_generated") {
        Some(Value::String(s)) if !s.is_empty() => s.clone(),
        _ => generated_stamp(),
    };
    let mut out = Map::new();
    out.insert("_generated".into(), Value::String(stamp));
    for (k, v) in data {
        if k != "_generated" {
            out.insert(k, v);
        }
    }
    write_json_atomic(&mem_path(), &Value::Object(out))
}

/// Neuer Erzeugungs-Stempel, genau wie in Python
/// (`"generated by PyGameZ at <Datum Zeit> (YYYY-MM-DD HH:MM:SS)"`).
pub fn generated_stamp() -> String {
    format!("generated by PyGameZ at {} (YYYY-MM-DD HH:MM:SS)", timestamp())
}

fn section_is_shared(name: &str) -> bool {
    SHARED_SECTIONS.contains(&name)
}

/// Liest einen Abschnitt des aktiven Profils (leer, wenn er fehlt).
pub fn load_section(name: &str) -> Section {
    load_section_of(name, None)
}

/// Liest einen Abschnitt eines bestimmten Profils.
pub fn load_section_of(name: &str, profile: Option<&str>) -> Section {
    let data = load();
    if section_is_shared(name) {
        return data
            .get(name)
            .and_then(|v| v.as_object())
            .cloned()
            .unwrap_or_default();
    }
    let pid = profile.map(str::to_string).unwrap_or_else(|| active_of(&data));
    data.get(PLAYERS)
        .and_then(|v| v.as_object())
        .and_then(|p| p.get(&pid))
        .and_then(|v| v.as_object())
        .and_then(|p| p.get(name))
        .and_then(|v| v.as_object())
        .cloned()
        .unwrap_or_default()
}

/// Schreibt einen Abschnitt des aktiven Profils zurueck.
pub fn save_section(name: &str, section: Section) -> bool {
    save_section_of(name, section, None)
}

/// Schreibt einen Abschnitt eines bestimmten Profils zurueck.
pub fn save_section_of(name: &str, section: Section, profile: Option<&str>) -> bool {
    let _guard = lock();
    let mut data = load();
    if section_is_shared(name) {
        data.insert(name.into(), Value::Object(section));
        return save(data);
    }
    let pid = profile.map(str::to_string).unwrap_or_else(|| active_of(&data));
    let players = data
        .entry(PLAYERS.to_string())
        .or_insert_with(|| json!({}))
        .as_object_mut();
    if let Some(players) = players {
        let entry = players
            .entry(pid)
            .or_insert_with(|| json!({}))
            .as_object_mut();
        if let Some(entry) = entry {
            entry.insert(name.into(), Value::Object(section));
        }
    }
    save(data)
}

/// Serialisiert Schreibzugriffe (lesen -> aendern -> schreiben).
fn lock() -> std::sync::MutexGuard<'static, ()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
        .lock()
        .unwrap_or_else(|e| e.into_inner())
}

fn active_of(data: &Map<String, Value>) -> String {
    data.get(PROFILES)
        .and_then(|v| v.get("active"))
        .and_then(|v| v.as_str())
        .unwrap_or(FIRST_ID)
        .to_string()
}

// ---------------------------------------------------------------------------
// Profile
// ---------------------------------------------------------------------------

/// id des aktiven Profils.
pub fn active_id() -> String {
    active_of(&load())
}

/// Alle Profil-ids in Anzeige-Reihenfolge.
pub fn profile_ids() -> Vec<String> {
    load()
        .get(PROFILES)
        .and_then(|v| v.get("order"))
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_else(|| vec![FIRST_ID.into()])
}

/// Kopfdaten eines Profils (`None` = aktives Profil).
pub fn profile_meta(pid: Option<&str>) -> ProfileMeta {
    let data = load();
    let id = pid.map(str::to_string).unwrap_or_else(|| active_of(&data));
    data.get(PROFILES)
        .and_then(|v| v.get("list"))
        .and_then(|v| v.get(&id))
        .map(|raw| ProfileMeta::from_value(raw, ""))
        .unwrap_or_default()
}

/// `[(id, Kopfdaten), ...]` in Anzeige-Reihenfolge.
pub fn all_profiles() -> Vec<(String, ProfileMeta)> {
    let data = load();
    let list = data.get(PROFILES).and_then(|v| v.get("list"));
    profile_ids()
        .into_iter()
        .map(|id| {
            let meta = list
                .and_then(|l| l.get(&id))
                .map(|raw| ProfileMeta::from_value(raw, ""))
                .unwrap_or_default();
            (id, meta)
        })
        .collect()
}

/// Aendert einzelne Kopfdaten eines Profils.
pub fn set_meta(pid: &str, edit: impl FnOnce(&mut ProfileMeta)) -> bool {
    let _guard = lock();
    let mut data = load();
    let mut meta = data
        .get(PROFILES)
        .and_then(|v| v.get("list"))
        .and_then(|v| v.get(pid))
        .map(|raw| ProfileMeta::from_value(raw, ""))
        .unwrap_or_default();
    edit(&mut meta);
    let Some(list) = data
        .get_mut(PROFILES)
        .and_then(|v| v.get_mut("list"))
        .and_then(|v| v.as_object_mut())
    else {
        return false;
    };
    if !list.contains_key(pid) {
        return false;
    }
    list.insert(pid.into(), meta.to_value());
    save(data)
}

/// Merkt sich den letzten Besuch eines Profils.
pub fn touch(pid: Option<&str>) {
    let id = pid.map(str::to_string).unwrap_or_else(active_id);
    set_meta(&id, |m| m.seen = stamp_minute());
}

fn next_id(existing: &[String]) -> String {
    for n in 1..=(MAX_PROFILES + 1) {
        let id = format!("p{n}");
        if !existing.contains(&id) {
            return id;
        }
    }
    format!("p{}", existing.len() + 1)
}

/// Legt ein Profil an; gibt dessen id zurueck (`None`, wenn kein Platz ist).
pub fn create_profile(name: &str, icon: &str, color: i64) -> Option<String> {
    let _guard = lock();
    let mut data = load();
    let ids: Vec<String> = data
        .get(PROFILES)
        .and_then(|v| v.get("order"))
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();
    if ids.len() >= MAX_PROFILES {
        return None;
    }
    let id = next_id(&ids);
    let meta = ProfileMeta {
        name: name.trim().chars().take(crate::profiles::MAX_NAME).collect(),
        icon: icon.to_string(),
        color,
        ..Default::default()
    };
    let profiles = data
        .get_mut(PROFILES)
        .and_then(|v| v.as_object_mut())
        .expect("normalize() legt den profiles-Abschnitt immer an");
    if let Some(order) = profiles.get_mut("order").and_then(|v| v.as_array_mut()) {
        order.push(Value::String(id.clone()));
    }
    if let Some(list) = profiles.get_mut("list").and_then(|v| v.as_object_mut()) {
        list.insert(id.clone(), meta.to_value());
    }
    if let Some(players) = data.get_mut(PLAYERS).and_then(|v| v.as_object_mut()) {
        players.insert(id.clone(), json!({}));
    }
    if save(data) {
        Some(id)
    } else {
        None
    }
}

/// Loescht ein Profil samt Daten (das letzte Profil bleibt bestehen).
pub fn delete_profile(pid: &str) -> bool {
    let _guard = lock();
    let mut data = load();
    let ids: Vec<String> = data
        .get(PROFILES)
        .and_then(|v| v.get("order"))
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();
    if ids.len() <= 1 || !ids.contains(&pid.to_string()) {
        return false;
    }
    let profiles = data
        .get_mut(PROFILES)
        .and_then(|v| v.as_object_mut())
        .expect("normalize() legt den profiles-Abschnitt immer an");
    if let Some(order) = profiles.get_mut("order").and_then(|v| v.as_array_mut()) {
        order.retain(|v| v.as_str() != Some(pid));
    }
    if let Some(list) = profiles.get_mut("list").and_then(|v| v.as_object_mut()) {
        list.shift_remove(pid);
    }
    let remaining = profiles
        .get("order")
        .and_then(|v| v.as_array())
        .and_then(|a| a.first())
        .and_then(|v| v.as_str())
        .unwrap_or(FIRST_ID)
        .to_string();
    let was_active = profiles.get("active").and_then(|v| v.as_str()) == Some(pid);
    if was_active {
        profiles.insert("active".into(), Value::String(remaining));
    }
    if let Some(players) = data.get_mut(PLAYERS).and_then(|v| v.as_object_mut()) {
        players.shift_remove(pid);
    }
    let ok = save(data);
    if ok && was_active {
        fire_switch();
    }
    ok
}

/// Wechselt das aktive Profil (leert ueber [`on_switch`] alle Zwischenspeicher).
pub fn set_active(pid: &str) -> bool {
    let ok = {
        let _guard = lock();
        let mut data = load();
        let known = data
            .get(PROFILES)
            .and_then(|v| v.get("order"))
            .and_then(|v| v.as_array())
            .map(|a| a.iter().any(|v| v.as_str() == Some(pid)))
            .unwrap_or(false);
        if !known {
            return false;
        }
        if let Some(profiles) = data.get_mut(PROFILES).and_then(|v| v.as_object_mut()) {
            profiles.insert("active".into(), Value::String(pid.into()));
        }
        save(data)
    };
    if ok {
        fire_switch();
    }
    ok
}

// ---------------------------------------------------------------------------
// Rueckrufe beim Profilwechsel
// ---------------------------------------------------------------------------

/// Die angemeldeten Rueckrufe fuer den Profilwechsel.
type SwitchCallbacks = OnceLock<Mutex<Vec<fn()>>>;

static SWITCH_CALLBACKS: SwitchCallbacks = OnceLock::new();

/// Meldet einen Rueckruf an, der nach jedem Profilwechsel laeuft.
///
/// Jedes Modul mit Zwischenspeicher (stats, achievements, lamabank ...) muss
/// sich hier eintragen - sonst zeigt es nach dem Wechsel die Daten des alten
/// Profils.
pub fn on_switch(callback: fn()) {
    SWITCH_CALLBACKS
        .get_or_init(|| Mutex::new(Vec::new()))
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .push(callback);
}

fn fire_switch() {
    let list = SWITCH_CALLBACKS
        .get_or_init(|| Mutex::new(Vec::new()))
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .clone();
    for cb in list {
        cb();
    }
}

/// Einmalig beim Programmstart: Datei normalisieren (geschrieben wird nur,
/// wenn dabei etwas umgebaut wurde).
pub fn init() {
    let _guard = lock();
    // Wie Python (i18n.init -> store.load): die Datei wird nur geschrieben,
    // wenn load() beim Normalisieren etwas umbauen musste.
    let _ = load();
}

// ---------------------------------------------------------------------------
// Kleine Helfer fuer die Abschnitte
// ---------------------------------------------------------------------------

/// Liest eine Ganzzahl aus einem Abschnitt.
pub fn get_i64(section: &Section, key: &str, default: i64) -> i64 {
    section.get(key).and_then(|v| v.as_i64()).unwrap_or(default)
}

/// Liest einen Wahrheitswert aus einem Abschnitt.
pub fn get_bool(section: &Section, key: &str, default: bool) -> bool {
    section.get(key).and_then(|v| v.as_bool()).unwrap_or(default)
}

/// Liest eine Zeichenkette aus einem Abschnitt.
pub fn get_str(section: &Section, key: &str, default: &str) -> String {
    section
        .get(key)
        .and_then(|v| v.as_str())
        .unwrap_or(default)
        .to_string()
}

// ---------------------------------------------------------------------------
// Eigener Spielstand eines Spiels
// ---------------------------------------------------------------------------

/// Der eigene Speicherbereich eines Spiels in `mem.json`.
///
/// Jedes Spiel darf unter seinem Schluessel ablegen, was es braucht:
/// Bestzeiten, Level-Fortschritt, ein angefangenes Brett zum Fortsetzen.
/// Das ist das Gegenstueck zu `store.load_section("tetris")` in Python -
/// und der Weg, wie ein Spiel etwas speichert, das **keine Option** ist
/// (Optionen gehoeren nach `settings.json`, siehe [`crate::settings`]).
///
/// Die Daten liegen beim aktiven Profil; nach einem Profilwechsel liest
/// ein neues [`GameData::load`] automatisch den Stand des neuen Spielers.
///
/// ```no_run
/// use pgz_core::store::GameData;
///
/// let mut daten = GameData::load("minesweeper");
/// let bestzeit = daten.get_i64("best_time_0", 0);
/// daten.set_i64("best_time_0", 42);
/// daten.save();
/// ```
#[derive(Debug, Clone)]
pub struct GameData {
    key: String,
    data: Section,
}

impl GameData {
    /// Laedt den Spielstand eines Spiels (leer, wenn es noch keinen gibt).
    pub fn load(key: &str) -> Self {
        Self {
            key: key.to_string(),
            data: load_section(key),
        }
    }

    /// Schreibt den Spielstand zurueck.
    pub fn save(&self) -> bool {
        save_section(&self.key, self.data.clone())
    }

    /// True, wenn noch nichts gespeichert ist.
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    /// Ganzzahl lesen.
    pub fn get_i64(&self, key: &str, default: i64) -> i64 {
        get_i64(&self.data, key, default)
    }

    /// Ganzzahl schreiben.
    pub fn set_i64(&mut self, key: &str, value: i64) {
        self.data.insert(key.into(), Value::from(value));
    }

    /// Kommazahl lesen (fuer Zeiten).
    pub fn get_f64(&self, key: &str, default: f64) -> f64 {
        self.data
            .get(key)
            .and_then(|v| v.as_f64())
            .unwrap_or(default)
    }

    /// Kommazahl schreiben.
    pub fn set_f64(&mut self, key: &str, value: f64) {
        self.data.insert(key.into(), json!(value));
    }

    /// Wahrheitswert lesen.
    pub fn get_bool(&self, key: &str, default: bool) -> bool {
        get_bool(&self.data, key, default)
    }

    /// Wahrheitswert schreiben.
    pub fn set_bool(&mut self, key: &str, value: bool) {
        self.data.insert(key.into(), Value::Bool(value));
    }

    /// Text lesen.
    pub fn get_str(&self, key: &str, default: &str) -> String {
        get_str(&self.data, key, default)
    }

    /// Text schreiben.
    pub fn set_str(&mut self, key: &str, value: &str) {
        self.data.insert(key.into(), Value::String(value.into()));
    }

    /// Zahlenliste lesen - fuer ein angefangenes Spielbrett.
    pub fn get_ints(&self, key: &str) -> Vec<i64> {
        self.data
            .get(key)
            .and_then(|v| v.as_array())
            .map(|a| a.iter().filter_map(|x| x.as_i64()).collect())
            .unwrap_or_default()
    }

    /// Zahlenliste schreiben.
    pub fn set_ints(&mut self, key: &str, values: &[i64]) {
        self.data.insert(key.into(), json!(values));
    }

    /// Eine `{Text: Zahl}`-Tabelle lesen (Bestwerte je Stufe, Fortschritt).
    pub fn get_counts(&self, key: &str) -> BTreeMap<String, i64> {
        get_counts(&self.data, key)
    }

    /// Eine `{Text: Zahl}`-Tabelle schreiben.
    pub fn set_counts(&mut self, key: &str, values: &BTreeMap<String, i64>) {
        let map: Map<String, Value> = values
            .iter()
            .map(|(k, v)| (k.clone(), Value::from(*v)))
            .collect();
        self.data.insert(key.into(), Value::Object(map));
    }

    /// Einen Eintrag loeschen.
    pub fn remove(&mut self, key: &str) {
        self.data.shift_remove(key);
    }

    /// Alles loeschen (Spielstand verwerfen).
    pub fn clear(&mut self) {
        self.data.clear();
    }

    /// Merkt sich einen Bestwert, wenn er besser ist als der gespeicherte.
    ///
    /// `kleiner_ist_besser` fuer Zeiten und Zugzahlen. Gibt `true` zurueck,
    /// wenn es ein neuer Bestwert war.
    pub fn record_best(&mut self, key: &str, value: i64, kleiner_ist_besser: bool) -> bool {
        let alt = self.data.get(key).and_then(|v| v.as_i64());
        let besser = match alt {
            None => true,
            Some(alt) if kleiner_ist_besser => value < alt,
            Some(alt) => value > alt,
        };
        if besser {
            self.set_i64(key, value);
        }
        besser
    }
}

/// Liest eine `{Text: Zahl}`-Tabelle (Highscores, Zaehler ...).
pub fn get_counts(section: &Section, key: &str) -> BTreeMap<String, i64> {
    section
        .get(key)
        .and_then(|v| v.as_object())
        .map(|o| {
            o.iter()
                .filter_map(|(k, v)| v.as_i64().map(|n| (k.clone(), n)))
                .collect()
        })
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spielstand_haelt_alle_werte() {
        let mut d = GameData {
            key: "probe".into(),
            data: Section::new(),
        };
        assert!(d.is_empty());
        d.set_i64("zahl", 42);
        d.set_f64("zeit", 12.5);
        d.set_bool("fertig", true);
        d.set_str("modus", "classic");
        d.set_ints("brett", &[1, 2, 3, 0]);
        assert_eq!(d.get_i64("zahl", 0), 42);
        assert_eq!(d.get_f64("zeit", 0.0), 12.5);
        assert!(d.get_bool("fertig", false));
        assert_eq!(d.get_str("modus", ""), "classic");
        assert_eq!(d.get_ints("brett"), vec![1, 2, 3, 0]);
        // Fehlende Werte liefern den Standard.
        assert_eq!(d.get_i64("gibt-es-nicht", 7), 7);
        assert!(d.get_ints("gibt-es-nicht").is_empty());
        d.remove("zahl");
        assert_eq!(d.get_i64("zahl", 0), 0);
        d.clear();
        assert!(d.is_empty());
    }

    #[test]
    fn bestwert_merkt_sich_nur_das_bessere() {
        let mut d = GameData {
            key: "probe".into(),
            data: Section::new(),
        };
        // Grosse Punktzahl: mehr ist besser.
        assert!(d.record_best("score", 100, false), "der erste Wert zaehlt");
        assert!(!d.record_best("score", 50, false));
        assert!(d.record_best("score", 200, false));
        assert_eq!(d.get_i64("score", 0), 200);

        // Zeit: weniger ist besser.
        assert!(d.record_best("time", 90, true));
        assert!(!d.record_best("time", 120, true));
        assert!(d.record_best("time", 60, true));
        assert_eq!(d.get_i64("time", 0), 60);
    }

    #[test]
    fn datum_wird_richtig_gerechnet() {
        // Probe gegen bekannte Zeitpunkte (UTC).
        assert_eq!(civil_from_unix(0), (1970, 1, 1, 0, 0, 0));
        assert_eq!(civil_from_unix(86_399), (1970, 1, 1, 23, 59, 59));
        assert_eq!(civil_from_unix(1_000_000_000), (2001, 9, 9, 1, 46, 40));
    }
}
